class Solution {
    public int[][] zeroTriples(int[] values) {
        int n = values.length;
        TreeSet<List<Integer>> found = new TreeSet<>((x, y) -> {
            for (int t = 0; t < 3; t++) if (!x.get(t).equals(y.get(t))) return Integer.compare(x.get(t), y.get(t));
            return 0;
        });
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                for (int k = j + 1; k < n; k++)
                    if (values[i] + values[j] + values[k] == 0) {
                        Integer[] t = {values[i], values[j], values[k]};
                        Arrays.sort(t);
                        found.add(Arrays.asList(t));
                    }
        int[][] out = new int[found.size()][];
        int r = 0;
        for (List<Integer> t : found) out[r++] = new int[] {t.get(0), t.get(1), t.get(2)};
        return out;
    }
}

