        set<vector<int>> found;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                for (int k = j + 1; k < n; k++)
                    if (values[i] + values[j] + values[k] == 0) {
                        vector<int> t = {values[i], values[j], values[k]};
                        sort(t.begin(), t.end());
