static int cmp3(const void* x, const void* y) {
    const int *a = *(int* const*) x, *b = *(int* const*) y;
    for (int t = 0; t < 3; t++) if (a[t] != b[t]) return (a[t] > b[t]) - (a[t] < b[t]);
    return 0;
}

int** zeroTriples(int* values, int valuesSize, int* returnSize, int** returnColumnSizes) {
    int n = valuesSize, cap = 16, m = 0;
    int** found = malloc(cap * sizeof(int*));
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++)
            for (int k = j + 1; k < n; k++)
                if (values[i] + values[j] + values[k] == 0) {
                    int t[3] = {values[i], values[j], values[k]};
                    if (t[0] > t[1]) { int s = t[0]; t[0] = t[1]; t[1] = s; }
                    if (t[1] > t[2]) { int s = t[1]; t[1] = t[2]; t[2] = s; }
                    if (t[0] > t[1]) { int s = t[0]; t[0] = t[1]; t[1] = s; }
                    if (m == cap) found = realloc(found, (cap *= 2) * sizeof(int*));
                    found[m] = malloc(3 * sizeof(int));
                    memcpy(found[m++], t, sizeof t);
                }
    qsort(found, m, sizeof(int*), cmp3);
    int w = 0;
    for (int r = 0; r < m; r++) {
        if (w && cmp3(&found[w - 1], &found[r]) == 0) { free(found[r]); continue; }
        found[w++] = found[r];
    }
    *returnSize = w;
    *returnColumnSizes = malloc((w + 1) * sizeof(int));
    for (int r = 0; r < w; r++) (*returnColumnSizes)[r] = 3;
    return found;
}

