static int cmp_int(const void* x, const void* y) {
    int a = *(const int*) x, b = *(const int*) y;
    return (a > b) - (a < b);
}

int** zeroTriples(int* values, int valuesSize, int* returnSize, int** returnColumnSizes) {
    int n = valuesSize, cap = 16, m = 0;
    int* a = malloc(n * sizeof(int));
    memcpy(a, values, n * sizeof(int));
    qsort(a, n, sizeof(int), cmp_int);
    int** out = malloc(cap * sizeof(int*));
    for (int i = 0; i + 2 < n; i++) {
        if (i > 0 && a[i] == a[i - 1]) continue;
        if (a[i] > 0) break;
        int j = i + 1, k = n - 1;
        while (j < k) {
            int s = a[i] + a[j] + a[k];
            if (s < 0) j++;
            else if (s > 0) k--;
            else {
                if (m == cap) out = realloc(out, (cap *= 2) * sizeof(int*));
                out[m] = malloc(3 * sizeof(int));
                out[m][0] = a[i]; out[m][1] = a[j]; out[m][2] = a[k];
                m++;
                j++;
                while (j < k && a[j] == a[j - 1]) j++;
                k--;
            }
        }
    }
    free(a);
    *returnSize = m;
    *returnColumnSizes = malloc((m + 1) * sizeof(int));
    for (int r = 0; r < m; r++) (*returnColumnSizes)[r] = 3;
    return out;
}
